import {Button, Form, Input, message, Modal} from "antd";
import React from "react";
import {LockOutlined, UserOutlined} from "@ant-design/icons";
import {signup} from "../utils";


class SignupForm extends React.Component {

  state = {
    displayModal: false,
    loading: false
  };

  handleCancel = () => {
    this.setState({displayModal: false});
  }

  signUpOnClick = () => {
    this.setState({displayModal: true});
  }


  onFinish = (data) => {
    this.setState({loading: true});
    signup(data)
      .then(response => {
        message.success('Signup successful');
        this.props.onSuccess(response);
      })
      .catch(error => {
        message.error('Signup failed: ' + error.message);
      })
      .finally(() => {
        this.setState({loading: false});
      });
  };
  render() {
    return (

      <>
        <Button shape="round" type="primary" onClick={this.signUpOnClick}>
          Sign Up
        </Button>
        <Modal
          title="Sign Up"
          visible={this.state.displayModal}
          onCancel={this.handleCancel}
          footer={null}
          destroyOnClose={true}
        >
          <Form
            name="signup_form"
            onFinish={this.onFinish}
            initialValues={{remember: true}}
            style={{maxWidth: '300px', margin: '0 auto'}}
            preserve={false}
          >
            <Form.Item
              name="email"
              rules={[{required: true, message: 'Please input your email!'}]}
            >
              <Input prefix={<UserOutlined className="site-form-item-icon"/>} placeholder="example@email.com"/>
            </Form.Item>
            <Form.Item
              name="password"
              rules={[{required: true, message: 'Please input your Password!'}]}
            >
              <Input
                prefix={<LockOutlined className="site-form-item-icon"/>}
                type="password"
                placeholder="Password"
              />
            </Form.Item>
            <Form.Item
              name="confirm"
              dependencies={['password']}
              hasFeedback
              rules={[
                { required: true, message: 'Please confirm your password!' },
                ({ getFieldValue }) => ({
                  validator(_, value) {
                    if (!value || getFieldValue('password') === value) {
                      return Promise.resolve();
                    }
                    return Promise.reject(new Error('The passwords that you entered do not match!'));
                  },
                }),
              ]}
            >
              <Input.Password
                prefix={<LockOutlined className="site-form-item-icon" />}
                placeholder="Confirm Password"
              />
            </Form.Item>
            <Form.Item
              name="first_name"
              rules={[{required: true, message: 'Please input your First Name!'}]}
            >
              <Input prefix={<UserOutlined className="site-form-item-icon"/>} placeholder="Jamie"/>
            </Form.Item>
            <Form.Item
              name="last_name"
              rules={[{required: true, message: 'Please input your Last Name!'}]}
            >
              <Input prefix={<UserOutlined className="site-form-item-icon"/>} placeholder="Smith"/>
            </Form.Item>
            <Form.Item>
              <Button type="primary" htmlType="submit" className="signup-form-button" loading={this.state.loading}>
                Sign Up
              </Button>
            </Form.Item>
          </Form>
        </Modal>
      </>
    );
  }
}
export default SignupForm;
