import {Button, Drawer, List, message, Space, Typography} from "antd";
import {useEffect, useState} from "react";
import {fetchCart, removeFromCart, addToCart, checkout,} from "../utils";

const {Text} = Typography;




const MyCart = () => {
  const [cartVisible, setCartVisible] = useState(false);
  const [cartData, setCartData] = useState();
  const [loading, setLoading] = useState(false);
  const [checkoutLoading, setCheckoutLoading] = useState(false);


  const onClose = () => {
    setCartVisible(false);
  };

  const onOpen = () => {
    setCartVisible(true);
  };

  
  useEffect(() => {
    if (!cartVisible) return;
    setLoading(true);
    fetchCart()
      .then(data => {
        setCartData(data);
      })
      .catch(error => {
        message.error('Failed to load cart: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
      });
  }, [cartVisible]);



  const loadCart = () => {
    if (!cartVisible) return;
    setLoading(true);
    fetchCart()
      .then(data => {
        setCartData(data);
      })
      .catch(error => {
        message.error('Failed to load cart: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  

  const handleRemoveFromCart = (itemId) => {
    setLoading(true);
    removeFromCart(itemId)
      .then(response => {
        message.success('Item removed from cart');
        loadCart();
      })
      .catch(error => {
        message.error('Failed to remove item from cart: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const handleAddToCart = (itemId) => {
    setLoading(true);
    addToCart(itemId)
      .then(response => {
        message.success('Item added to cart');
        loadCart();
      })
      .catch(error => {
        message.error('Failed to add item to cart: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  const handleCheckout = () => {

    setCheckoutLoading(true); 
    checkout()
      .then(response => {
        message.success('Checkout successful');
        loadCart();
      })
      .catch(error => {
        message.error('Checkout failed: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
        setCheckoutLoading(false);
      });
  };

  return (
    <>
      <Button type="primary" onClick={onOpen}>
        View Cart
      </Button>
      <Drawer
        title="My Cart"
        onClose={onClose}
        open={cartVisible}
        width={400}
        footer={
          <div style={{display: 'flex', 
          justifyContent: 'space-between'}}>
            <Text strong={true}>Total: ${cartData?.total?.toFixed(2)}</Text>
            <div>
              <Button onClick={onClose}>Close</Button>
              <Button type="primary" onClick={handleCheckout} loading={checkoutLoading} disabled={loading ||cartData?.items && cartData?.items.length === 0}>
                Checkout
              </Button>
            </div>
          </div>
        }
      >
        <List
          loading={loading}
          dataSource={cartData?.items}
          renderItem={item => (
            <List.Item
              actions={[
                <Button onClick={() => handleRemoveFromCart(item.menuId)}>-</Button>,
                <Button onClick={() => handleAddToCart(item.menuId)}>+</Button>
              ]}
            >
              <List.Item.Meta
                title={item.name}
                description={`Quantity: ${item.quantity}`}
              />
            </List.Item>
          )}
        />
        <Space style={{marginTop: '16px'}}>
          <Button type="primary" onClick={handleCheckout} disabled={cartData?.items && cartData?.items.length === 0}>
            Checkout
          </Button>
        </Space>
      </Drawer>
    </>
    
  );
};

export default MyCart;