import {Button, Card, List, message, Select, Tooltip} from "antd";
import React, {useEffect, useState} from "react";
import {addToCart, removeFromCart, fetchMenus, fetchShops} from "../utils";
import {ShoppingCartOutlined, PlusOutlined, MinusOutlined} from "@ant-design/icons";

const {Option} = Select;

const AddToCartButton = ({itemId}) => {
  const [loading, setLoading] = useState(false);

  const AddToCart = () => {
    setLoading(true);
    addToCart(itemId)
      .then(response => {
        message.success('Item added to cart');
      })
      .catch(error => {
        message.error('Failed to add item to cart: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  return (
    <Tooltip title="Add to Cart">
      <Button
        type="primary"
        icon={<PlusOutlined />}
        onClick={AddToCart}
        loading={loading}
      />
    </Tooltip>
  );
};

const RemoveFromCartButton = ({itemId}) => {
  const [loading, setLoading] = useState(false);

  const RemoveFromCart = () => {
    setLoading(true);
    removeFromCart(itemId)
      .then(response => {
        message.success('Item removed from cart');
      })
      .catch(error => {
        message.error('Failed to remove item from cart: ' + error.message);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  return (
    <Tooltip title="Remove from Cart">
      <Button
        type="primary"
        icon={<MinusOutlined />}
        onClick={RemoveFromCart}
        loading={loading}
      />
    </Tooltip>
  );
};

const FoodList = () => {
  const [menus, setMenus] = useState([]);
  const [shops, setShops] = useState([]);
  const [selectedShop, setSelectedShop] = useState();
  const [loading, setLoading] = useState(false);
  const [loadingShops, setLoadingShops] = useState(false);
  
  useEffect(() => {
    setLoadingShops(true);
    fetchShops()
      .then(data => {
        setShops(data);
      })
      .catch(error => {
        message.error('Failed to fetch shops: ' + error.message);
      })
      .finally(() => {
        setLoadingShops(false);
      });
  }, []);

  useEffect(() => {
    if (selectedShop) {
      setLoading(true);
      fetchMenus(selectedShop)
        .then(data => {
          setMenus(data);
        })
        .catch(error => {
          message.error('Failed to fetch menus: ' + error.message);
        })
        .finally(() => {
          setLoading(false);
        });
    }
  }, [selectedShop]);

  return (
    <div>
      <Select
        value={selectedShop}
        onSelect={value => setSelectedShop(value)}
        placeholder="Select a shop"
        loading={loadingShops}
        style={{width: 200, marginBottom: 20}}
        onChange={()=>{}}
      >
        {shops.map((item) => {
          return <Option value={item.id}>{item.name}</Option>;
        })}
      </Select>
      {selectedShop && 
      <List
        grid={{ gutter: 16, 
                xs: 1,
                sm: 2,
                md: 4,
                lg: 4,
                xl: 3,
                xxl: 3 }}
        dataSource={menus}
        loading={loading}
        renderItem={item => (
          <List.Item>
            <Card

              title={item.name}
              extra={<>
                <AddToCartButton itemId={item.id} />
                <RemoveFromCartButton itemId={item.id} />
              </>}
            >
              <img src={item.imageUrl} alt={item.name} 
                style={{width: '100%', 
                        display: 'block',
                        height: '150px', 
                        objectFit: 'cover', 
                        marginBottom: '10px'}} />
              <p>{item.description}</p>
              <p>Price: ${item.price}</p>
            </Card>
          </List.Item>
        )}
      />}
      {selectedShop && menus.length === 0 && !loading && 
      <p>No items available for this shop.</p>}
    </div>
  );

}
export default FoodList;
